#include <vector>
#include <map>
#include <type_traits>
template <typename T> std::string dbg(const T& x);
template <typename T> std::string dbg(const std::vector<T>& x) {
    std::ostringstream oss; oss << "["; bool first=true;
    for (auto& e : x) { if(!first) oss << ","; oss << dbg(e); first=false; }
    oss << "]"; return oss.str();
}
template <typename T> std::string dbg(const std::map<std::string,T>& x) {
    std::ostringstream oss; bool first=true;
    for (auto& [k,val] : x) { if(!first) oss << ","; oss << k << "=" << dbg(val); first=false; }
    return oss.str();
}
template <typename T> std::string dbg(const T& x) {
    std::ostringstream oss; oss << x; return oss.str();
}

